"""Soal IPAS KELAS 3 dari buku sekolah "Ilmu Pengetahuan Alam dan Sosial SD/MI Kelas III"
(Kemendikbudristek 2022, Amalia Fitri dkk.). Semester 1 = Bab 1–4. Bab 5–8 (semester 2) menyusul.
Jalankan: python3 tools/gen_ipas_k3.py  lalu  python3 tools/build_bank.py"""
import json

Q = []
def M(lvl, ch, q, right, wrong, ex, img=None):
    d = {"level": lvl, "ch": ch, "q": q, "choices": [right] + wrong, "answer": 0, "explain": ex}
    if img: d.update(img=img, imgSpeak="")
    Q.append(d)
def I(lvl, ch, q, ans, ex):
    alts = ans.split(";")
    Q.append({"level": lvl, "ch": ch, "type": "input", "q": q, "answer": alts[0], "accept": alts[1:], "explain": ex})
def U(ch, q, ans, kws):
    Q.append({"level": 3, "ch": ch, "type": "uraian", "q": q, "answer": ans, "keywords": kws})

# ===================== Bab 1 Mari Kenali Hewan di Sekitar Kita =====================
M(1, 1, "Hewan yang sengaja dipelihara, diberi makan, dan dirawat manusia disebut hewan …", "peliharaan", ["liar", "purba", "langka"], "Hewan peliharaan dirawat manusia, contohnya kucing.")
M(1, 1, "Contoh hewan peliharaan adalah …", "kucing", ["nyamuk", "belalang", "kelelawar"], "Kucing banyak dipelihara di rumah.", "🐈")
M(1, 1, "Hewan yang hidup di air adalah …", "ikan", ["kucing", "ayam", "kambing"], "Ikan hidup di air.", "🐟")
M(1, 1, "Kucing memiliki … kaki.", "4", ["2", "6", "0"], "Kucing berkaki empat, cacing tidak punya kaki.")
M(1, 1, "Cacing bergerak dengan cara …", "menggeliat", ["berjalan", "terbang", "melompat"], "Cacing tidak punya kaki, ia menggeliat.", "🪱")
M(2, 1, "Hewan yang memakan tumbuhan disebut …", "herbivora", ["karnivora", "omnivora", "amfibi"], "Herbivora = pemakan tumbuhan, contohnya sapi, kambing, kelinci.")
M(2, 1, "Hewan yang memakan daging (hewan lain) disebut …", "karnivora", ["herbivora", "omnivora", "mamalia"], "Karnivora = pemakan daging, contohnya harimau dan singa.")
M(2, 1, "Hewan pemakan tumbuhan dan daging disebut …", "omnivora", ["herbivora", "karnivora", "reptil"], "Omnivora memakan keduanya, contohnya monyet, tikus, babi.")
M(2, 1, "Contoh hewan herbivora adalah …", "kambing", ["harimau", "buaya", "singa"], "Kambing memakan rumput.", "🐐")
M(2, 1, "Hewan yang menyusui anaknya termasuk kelompok …", "mamalia", ["aves", "reptil", "pisces"], "Mamalia menyusui, contohnya kucing, sapi, monyet.")
M(3, 1, "Gigi taring pada harimau berguna untuk …", "mengoyak daging", ["mengunyah rumput", "memecah biji", "minum air"], "Karnivora punya taring untuk mengoyak daging.")
M(3, 1, "Ayam dan burung memiliki paruh yang kuat untuk …", "memecah biji-bijian", ["mengoyak daging", "berenang", "menggali tanah"], "Paruh kuat membantu menghancurkan biji-bijian.")
M(3, 1, "Kuku kucing runcing dan melengkung agar kucing mudah …", "memanjat", ["berenang", "terbang", "menggali"], "Kuku tajam mencengkeram pohon saat memanjat.")
M(3, 1, "Hewan yang hidup di dua alam (darat dan air) disebut amfibi. Contohnya …", "katak", ["ular", "burung", "kucing"], "Katak hidup di air dan di darat.", "🐸")
M(3, 1, "Ular, buaya, kadal, dan kura-kura termasuk kelompok …", "reptil", ["mamalia", "aves", "amfibi"], "Reptil adalah hewan melata.")
M(3, 1, "Hewan yang TIDAK memiliki tulang belakang disebut …", "invertebrata", ["vertebrata", "mamalia", "reptil"], "Invertebrata tidak punya tulang belakang, contohnya cacing, siput, kepiting.")
I(1, 1, "Hewan pemakan tumbuhan disebut … (herbivora/karnivora)", "herbivora", "Herbivora = pemakan tumbuhan.")
I(2, 1, "Sapi berkembang dan menyusui anaknya. Sapi termasuk hewan …", "mamalia", "Hewan menyusui = mamalia.")
I(2, 1, "Burung memiliki bulu dan termasuk kelompok … (aves/reptil)", "aves", "Aves = hewan berbulu, yaitu burung.")
I(3, 1, "Hewan yang memiliki tulang belakang disebut …", "vertebrata", "Vertebrata = bertulang belakang.")
U(1, "Mengapa bentuk tubuh hewan berbeda-beda? Berikan satu contoh!", "Karena bentuk tubuh hewan menyesuaikan makanan, tempat tinggal, dan cara bergeraknya supaya bisa bertahan hidup. Contoh: ikan punya sirip untuk berenang, kucing punya kuku tajam untuk memanjat.", ["makanan", "tempat tinggal", "bergerak", "bertahan hidup"])
U(1, "Sebutkan masing-masing satu contoh hewan herbivora, karnivora, dan omnivora!", "Herbivora: sapi/kambing/kelinci. Karnivora: harimau/singa/buaya. Omnivora: monyet/tikus/babi.", ["sapi", "kambing", "kelinci", "harimau", "singa", "monyet", "tikus"])

# ===================== Bab 2 Ayo, Mengenal Siklus pada Makhluk Hidup =====================
M(1, 2, "Salah satu ciri makhluk hidup adalah berkembang biak, artinya …", "menghasilkan keturunan", ["bergerak cepat", "makan banyak", "tidur lama"], "Berkembang biak = menghasilkan keturunan.")
M(1, 2, "Siklus artinya …", "putaran kejadian yang berulang", ["kejadian sekali saja", "gerakan lurus", "makanan hewan"], "Siklus digambarkan seperti lingkaran.")
M(1, 2, "Ayam berkembang biak dengan cara …", "bertelur", ["melahirkan", "membelah diri", "bertunas"], "Ayam bertelur lalu mengeraminya.", "🐔")
M(1, 2, "Sapi berkembang biak dengan cara …", "melahirkan", ["bertelur", "bertunas", "membelah diri"], "Sapi melahirkan anaknya.", "🐄")
M(1, 2, "Anak ulat jika sudah dewasa akan menjadi …", "kupu-kupu", ["belalang", "lebah", "nyamuk"], "Ulat → kepompong → kupu-kupu.", "🐛")
M(2, 2, "Siklus hidup manusia dimulai dari tahap …", "bayi", ["dewasa", "remaja", "lanjut usia"], "Bayi → anak-anak → remaja → dewasa → lanjut usia.")
M(2, 2, "Induk ayam mengerami telurnya selama sekitar …", "21 hari", ["2 hari", "9 bulan", "1 tahun"], "Telur ayam menetas setelah sekitar 21 hari.")
M(2, 2, "Hewan yang punah artinya …", "habis semua, tidak ada lagi", ["jarang ditemukan", "sedang tidur", "pindah rumah"], "Contohnya harimau Jawa dan burung dodo.")
M(2, 2, "Salah satu penyebab harimau Jawa punah adalah …", "hutan rusak dan perburuan", ["terlalu banyak makan", "cuaca dingin", "dipelihara manusia"], "Habitat rusak, makanan berkurang, dan perburuan.")
M(2, 2, "Perubahan bentuk tubuh pada siklus hidup hewan disebut …", "metamorfosis", ["fotosintesis", "berkembang biak", "adaptasi"], "Metamorfosis = perubahan bentuk.")
M(3, 2, "Urutan metamorfosis sempurna kupu-kupu yang benar adalah …", "telur – ulat – kepompong – kupu-kupu", ["telur – kepompong – ulat – kupu-kupu", "ulat – telur – kupu-kupu – kepompong", "telur – nimfa – kupu-kupu"], "Metamorfosis sempurna: telur → larva → pupa → dewasa.")
M(3, 2, "Metamorfosis tidak sempurna terdiri dari 3 fase, yaitu …", "telur – nimfa – dewasa", ["telur – larva – pupa – dewasa", "bayi – anak – dewasa", "telur – pupa – dewasa"], "Contohnya belalang, capung, kecoa.")
M(3, 2, "Hewan yang mengalami metamorfosis TIDAK sempurna adalah …", "belalang", ["kupu-kupu", "nyamuk", "katak"], "Belalang: telur → nimfa → dewasa.", "🦗")
M(3, 2, "Jentik-jentik adalah fase … pada nyamuk.", "larva", ["pupa", "dewasa", "nimfa"], "Telur nyamuk menetas menjadi jentik (larva) di air.", "🦟")
M(3, 2, "Nyamuk senang bertelur di …", "air yang tergenang", ["tanah kering", "pasir panas", "daun kering"], "Karena itu kita menguras dan menutup tempat penampungan air.")
M(3, 2, "Ular viper dan ikan gupi berkembang biak dengan cara …", "bertelur dan melahirkan", ["bertelur saja", "membelah diri", "bertunas"], "Telur menetas di dalam perut induknya, lalu anaknya dilahirkan.")
I(1, 2, "Kepompong disebut juga …", "pupa", "Pupa = kepompong.")
I(2, 2, "Tahap anak pada tumbuhan disebut … (bibit)", "benih;biji;bibit", "Tahap anak pada tumbuhan = benih.")
I(2, 2, "Metamorfosis sempurna terdiri dari … fase. (tulis angka)", "4;empat", "Telur, larva, pupa, dewasa.")
I(3, 2, "Hanya nyamuk … yang mengisap darah. (jantan/betina)", "betina", "Nyamuk betina butuh darah untuk telurnya.")
U(2, "Mengapa makhluk hidup perlu berkembang biak?", "Agar keturunannya tetap ada di Bumi (mempertahankan jenisnya) dan tidak punah.", ["keturunan", "punah", "jenis"])
U(2, "Sebutkan perbedaan metamorfosis sempurna dan tidak sempurna!", "Metamorfosis sempurna 4 fase: telur, larva, pupa, dewasa (contoh kupu-kupu). Tidak sempurna 3 fase: telur, nimfa, dewasa (contoh belalang).", ["4", "3", "larva", "pupa", "nimfa"])

# ===================== Bab 3 Hidup Bersama Alam =====================
M(1, 3, "Lingkungan tempat tinggal makhluk hidup disebut …", "habitat", ["populasi", "individu", "energi"], "Habitat = tempat tinggal.")
M(1, 3, "Makhluk hidup di suatu lingkungan disebut komponen …", "biotik", ["abiotik", "energi", "buatan"], "Biotik = makhluk hidup.")
M(1, 3, "Contoh komponen abiotik adalah …", "air", ["rumput", "ikan", "cacing"], "Abiotik = benda tidak hidup: tanah, air, udara, Matahari, batu.")
M(1, 3, "Contoh komponen biotik adalah …", "kupu-kupu", ["batu", "tanah", "udara"], "Kupu-kupu adalah makhluk hidup.")
M(1, 3, "Satu ekor kucing disebut …", "individu", ["populasi", "komunitas", "ekosistem"], "Satu makhluk hidup = individu.")
M(2, 3, "Sekelompok makhluk hidup SEJENIS di satu tempat disebut …", "populasi", ["individu", "komunitas", "habitat"], "Contoh: sekelompok ikan mas di kolam.")
M(2, 3, "Kumpulan makhluk hidup yang BERBEDA jenis dan hidup berdampingan disebut …", "komunitas", ["populasi", "individu", "abiotik"], "Contoh: ikan, katak, dan teratai di danau.")
M(2, 3, "Hubungan antara makhluk hidup dan benda tidak hidup di suatu lingkungan disebut …", "ekosistem", ["populasi", "simbiosis", "habitat"], "Ekosistem = komunitas + komponen abiotik yang saling berhubungan.")
M(2, 3, "Cacing tanah berperan membuat tanah menjadi …", "gembur", ["keras", "kering", "tercemar"], "Tanah gembur membuat tanaman tumbuh baik.", "🪱")
M(2, 3, "Akuarium adalah contoh ekosistem …", "buatan", ["hutan", "gurun", "sawah alami"], "Manusia membuat akuarium mirip ekosistem air.")
M(3, 3, "Hubungan yang khas antara dua makhluk hidup disebut …", "simbiosis", ["ekosistem", "metamorfosis", "habitat"], "Simbiosis ada tiga: mutualisme, komensalisme, parasitisme.")
M(3, 3, "Kupu-kupu dan bunga saling menguntungkan. Ini disebut simbiosis …", "mutualisme", ["parasitisme", "komensalisme", "metamorfosis"], "Kupu-kupu dapat nektar, bunga terbantu penyerbukannya.")
M(3, 3, "Anggrek menempel pada pohon. Anggrek untung, pohon tidak untung dan tidak rugi. Ini simbiosis …", "komensalisme", ["mutualisme", "parasitisme", "predasi"], "Komensalisme: satu untung, yang lain tidak dirugikan.")
M(3, 3, "Kutu mengisap darah kucing sehingga kucing gatal. Ini simbiosis …", "parasitisme", ["mutualisme", "komensalisme", "ekosistem"], "Parasitisme: satu untung, yang lain dirugikan.")
M(3, 3, "Tanaman air di kolam berguna untuk hewan air, KECUALI …", "membuat air menjadi kotor", ["menghasilkan udara", "tempat berlindung", "sumber makanan"], "Tanaman air (eceng gondok) justru menyerap kotoran.")
M(3, 3, "Jika pohon-pohon di hutan ditebang habis, yang terjadi adalah …", "hewan kehilangan tempat tinggal", ["hewan makin banyak", "udara makin segar", "tanah makin subur"], "Jika satu komponen rusak, makhluk hidup lain terganggu.")
I(1, 3, "Benda tidak hidup di lingkungan disebut komponen …", "abiotik", "Abiotik = tidak hidup.")
I(2, 3, "Sari bunga yang diisap kupu-kupu disebut …", "nektar", "Nektar = sari bunga.")
I(2, 3, "Satu makhluk hidup yang hidup sendiri disebut …", "individu", "Individu.")
I(3, 3, "Simbiosis yang saling menguntungkan disebut simbiosis …", "mutualisme", "Mutualisme = saling menguntungkan.")
U(3, "Sebutkan 2 komponen biotik dan 2 komponen abiotik di sekolahmu!", "Biotik: pohon, rumput, semut, burung, manusia. Abiotik: tanah, air, udara, batu, cahaya Matahari.", ["pohon", "rumput", "semut", "burung", "tanah", "air", "udara", "batu", "matahari"])
U(3, "Apa yang bisa kamu lakukan untuk menjaga ekosistem di sekitarmu?", "Tidak membuang sampah sembarangan, tidak mencabut tanaman atau mengganggu hewan, menanam pohon, menjaga kebersihan air.", ["sampah", "menanam", "tidak merusak", "mengganggu", "menjaga"])

# ===================== Bab 4 Berkenalan dengan Energi =====================
M(1, 4, "Lampu menghasilkan energi …", "cahaya", ["bunyi", "kimia", "gerak"], "Lampu membuat tempat gelap menjadi terang.", "💡")
