M(1, 4, "Gitar yang dipetik menghasilkan energi …", "bunyi", ["cahaya", "panas", "listrik"], "Dawai bergetar dan berbunyi.", "🎸")
M(1, 4, "Senter dan jam dinding memakai … sebagai sumber energinya.", "baterai", ["air", "angin", "kayu bakar"], "Baterai adalah sumber energi listrik.", "🔋")
M(2, 4, "Energi gerak disebut juga energi …", "kinetik", ["kimia", "listrik", "panas"], "Energi gerak = energi kinetik.")
M(2, 4, "Makanan yang kita makan mengandung energi …", "kimia", ["bunyi", "cahaya", "listrik"], "Tubuh mengolah makanan menjadi energi kimia.")
M(2, 4, "Menjemur pakaian agar kering memanfaatkan energi …", "panas", ["bunyi", "listrik", "kimia"], "Panas Matahari mengeringkan pakaian, ikan asin, kerupuk.")
M(2, 4, "TV, kulkas, dan komputer membutuhkan energi …", "listrik", ["bunyi", "kimia", "gerak"], "Alat elektronik memakai energi listrik.")
M(2, 4, "Angin dapat dimanfaatkan untuk …", "menerbangkan layang-layang", ["memasak nasi", "menyalakan senter", "menghangatkan air"], "Angin menghasilkan energi gerak, juga untuk kapal layar dan kincir angin.", "🪁")
M(3, 4, "Bensin, solar, gas elpiji, dan kayu bakar termasuk …", "bahan bakar", ["energi bunyi", "energi cahaya", "baterai"], "Bahan bakar menyimpan energi kimia; saat dibakar menjadi panas.")
M(3, 4, "Uap panas yang keluar dari dalam tanah di sekitar gunung berapi disebut …", "panas bumi", ["tenaga surya", "energi angin", "energi bunyi"], "Panas bumi bisa diubah menjadi listrik.")
M(3, 4, "Pembangkit listrik yang memakai sinar Matahari disebut tenaga …", "surya", ["air", "angin", "uap"], "Tenaga surya = tenaga Matahari.")
M(3, 4, "Cara menghemat listrik yang benar adalah …", "mematikan lampu saat tidak dipakai", ["menyalakan TV sepanjang hari", "membuka kulkas terus", "menyalakan lampu siang hari"], "Matikan alat elektronik yang tidak dipakai.")
M(3, 4, "Mengapa kita tidak boleh membuang-buang makanan?", "karena makanan adalah sumber energi", ["karena makanan berbunyi", "karena makanan menghasilkan listrik", "karena makanan tidak berguna"], "Membuang makanan = membuang energi; masih banyak orang yang butuh makan.")
M(3, 4, "Hewan yang punya listrik di tubuhnya adalah …", "belut listrik", ["kucing", "ayam", "kupu-kupu"], "Belut listrik dan ikan pari torpedo memakai listrik untuk melindungi diri.")
I(1, 4, "Bangun pagi dengan alarm memakai energi …", "bunyi", "Alarm berbunyi = energi bunyi.")
I(2, 4, "Pergi ke sekolah naik sepeda memakai energi …", "gerak;kinetik", "Bersepeda = energi gerak.")
I(2, 4, "Benda yang menyimpan energi disebut … energi.", "sumber", "Contoh sumber energi: baterai, Matahari, makanan.")
I(3, 4, "Mandi dan mencuci secukupnya adalah cara menghemat …", "air", "Gunakan air seperlunya.")
U(4, "Sebutkan 3 cara menghemat energi di rumah atau sekolah!", "Mematikan lampu dan alat elektronik yang tidak dipakai, memakai air secukupnya, menghabiskan makanan, memanfaatkan cahaya Matahari di siang hari.", ["mematikan", "lampu", "air", "makanan", "listrik"])
U(4, "Sebutkan 3 bentuk energi beserta contoh bendanya!", "Cahaya: lampu. Panas: kompor/setrika. Bunyi: gitar/radio. Gerak: kipas angin. Listrik: TV. Kimia: makanan/bensin.", ["cahaya", "panas", "bunyi", "gerak", "listrik", "kimia"])

json.dump({"ipas": Q}, open("data/_sumber/kelas3_ipas.json", "w", encoding="utf-8"), ensure_ascii=False, indent=1)
print(len(Q), "soal IPAS kelas 3")
